/**
 * @summary Upload a file
 */
export const getUploadDocumentUrl = () => {
  return `/api/documents/upload`;
};

export const uploadDocument = async (
  uploadDocumentBody: UploadDocumentBody,
  options?: RequestInit,
): Promise<Document> => {
  const formData = new FormData();
  if (uploadDocumentBody.file !== undefined) {
    formData.append(`file`, uploadDocumentBody.file);
  }
  if (uploadDocumentBody.caseId !== undefined) {
    formData.append(`caseId`, uploadDocumentBody.caseId.toString());
  }
  if (uploadDocumentBody.title !== undefined) {
    formData.append(`title`, uploadDocumentBody.title);
  }
  if (uploadDocumentBody.source !== undefined) {
    formData.append(`source`, uploadDocumentBody.source);
  }
  if (uploadDocumentBody.publishDate !== undefined) {
    formData.append(`publishDate`, uploadDocumentBody.publishDate);
  }

  return customFetch<Document>(getUploadDocumentUrl(), {
    ...options,
    method: "POST",
    body: formData,
  });
};

